    "question": "À propos des mécanismes des urticaires immunologiques",
    "propositions": {
      "A": "Ils ne nécessitent pas une sensibilisation préalable.",
      "B": "Ils sont induits par une hypersensibilité immédiate type anaphylactique médiée par les IgE ou IgG4.",
      "C": "L'hypersensibilité est médiée par la libération retardée d'acétylcholine.",
      "D": "Ils peuvent être induits par une hypersensibilité par activation du complément.",
      "E": "Les urticaires par vasculites sont exclues de ce groupe d'urticaire."
    },
