    "question": "Le score de sévérité d'une urticaire chronique ou Urticaria Activity Score (UAS)",
    "propositions": {
      "A": "Se calcule exclusivement par le nombre de papules (0 : aucune, 1 : moins de 10, 2 : de 10 à 50, 3 : plus de 50).",
      "B": "Se calcule exclusivement sur l'intensité des démangeaisons (0 : aucune, 1 : légères, 2 : modérées, 3 : sévères).",
      "C": "Le score combine le nombre de papules/jour et l'intensité du prurit/jour.",
      "D": "L'UAS 7 collecte les données sur 7 jours consécutifs.",
      "E": "L'urticaire est dite chronique uniquement si elle évolue depuis plus de 06 mois."
    },
