      "B": "La PUVAthérapie est une photochimiothérapie qui associe la prise orale d'un psoralène photosensibilisant et d'une irradiation avec ultraviolet A (UVA).",
      "C": "La puvathérapie est efficace dans toutes les formes de psoriasis.",
      "D": "La (re-puvathérapie) associe des rétinoïdes oraux à la puvathérapie et en augmente l'efficacité.",
      "E": "Elle accélère le vieillissement de la peau. Tableau du 25/05/2021, correspondance probable : BDE (statut officiel non établi)."
