    "question": "Le syndrome de Ritter-Leyell ou syndrome de Lyell staphylococcique encore mieux appelé : syndrome d'épidermolyse staphylococcique aigu",
    "propositions": {
      "A": "Il réalise la dermatite exfoliatrice de Ritter Von Rittershain du nourrisson.",
      "B": "Il complique une infection focale muqueuse (rhinopharyngite, otite, conjonctivite) ou cutanée (omphalite).",
      "C": "Il touche les grands plis, les régions périorificielles et s'étend rapidement sur tout le revêtement cutané.",
      "D": "La nécrolyse épidermique apparaît sous forme de décollements spontanés avec quelques bulles à toit fripé mais surtout déchirements par frottement provoqué (signe de Nikolski).",
      "E": "En dépit d'une prise en charge adaptée (antibiothérapie) l'évolution est toujours fatale."
    },
    "question_fr": "Le syndrome de Ritter-Leyell ou syndrome de Lyell staphylococcique encore mieux appelé : syndrome d'épidermolyse staphylococcique aigu",
    "bonnes_reponses": [
      "A",
      "B",
      "C",
      "D"
    ],
    "faculty": "Mostaganem",
