    "question": "À propos de l'érysipèle des membres inférieurs : cochez la réponse fausse",
    "propositions": {
      "A": "Il apparaît souvent sur des troubles trophiques : œdème ou eczéma de stase, insuffisance veineuse ou artérielle.",
      "B": "Il est souvent secondaire à un intertrigo infectieux ou à une effraction cutanée.",
      "C": "L'aspect typique est d'une grosse jambe rouge douloureuse, fébrile avec ADP inguinale.",
      "D": "L'héparinothérapie est impérative car risque élevé de TVP.",
      "E": "Pénicilline G reste le traitement de référence."
    },
