      "D": "Lorsque les lésions débordent sur la face plantaire et la face dorsale du pied et des orteils sous forme d'un processus vésiculeux et desquamatif il réalise l'aspect d'un « athletic foot ».",
      "E": "Cette dermatophytose est appelée aussi eczéma marginé de Hébra. Tableau du 25/05/2021, correspondance probable : ABCD (statut officiel non établi)."
