    "question": "L'impétigo est une infection cutanée superficielle de la peau",
    "propositions": {
      "A": "Elle est due exclusivement au staphylocoque.",
      "B": "C'est une dermatose plus fréquente chez l'adulte immunocompétent.",
      "C": "L'impétigo débute par une ou quelques lésions érythémateuses sur lesquelles surviennent des bulles fragiles à liquide clair ou légèrement trouble, entourées d'un liseré érythémateux, rapidement le contenu des bulles devient purulent, leur toit se rompt, laissant place à des croûtes jaunâtres mélicériques (couleur miel) et à des érosions arrondies groupées en élément annulaire.",
      "D": "Chez l'enfant l'impétigo siège le plus souvent sur le visage, près du nez et de la bouche.",
      "E": "Le traitement local par antiseptique est suffisant pour éviter la dissémination des lésions."
    },
    "question_fr": "L'impétigo est une infection cutanée superficielle de la peau",
    "bonnes_reponses": [
      "C",
      "D"
    ],
